function streamRows(week, genres) {
	return Array.from({ length: 20 }, (_, w) => genres.map((g, gi) => {
		const peak = [
			4,
			9,
			14,
			6,
			17,
			11
		][gi];
		const v = 6 + [
			38,
			30,
			14,
			20,
			26,
			22
		][gi] * Math.exp(-((w - peak) ** 2) / (2 * (3 + gi) ** 2)) + w * (gi + 3) % 4;
		return {
			week: week(w + 1),
			genre: g,
			hours: Math.round(v * 10) / 10
		};
	})).flat();
}
