function scatterRows(names, request) {
	const rnd = seeded(29);
	const models = [
		{
			model: names[0],
			cost: [5, 14],
			base: 1400,
			perCent: 150,
			sd: 260
		},
		{
			model: names[1],
			cost: [2, 7],
			base: 650,
			perCent: 150,
			sd: 170
		},
		{
			model: names[2],
			cost: [1, 3],
			base: 280,
			perCent: 130,
			sd: 90
		}
	];
	return Array.from({ length: 54 }, (_, i) => {
		const m = models[i % 3];
		const cost = Math.round(m.cost[0] + rnd() * (m.cost[1] - m.cost[0]));
		const ms = Math.max(120, Math.round((m.base + cost * m.perCent + gauss(rnd) * m.sd) / 10) * 10);
		return {
			id: `${request} ${i + 1}`,
			model: m.model,
			cost,
			ms
		};
	});
}
