function raceRows(brands) {
	const rnd = seeded(31);
	const base = [
		420,
		380,
		350,
		300,
		120,
		260,
		240,
		200,
		180,
		90,
		150,
		60
	];
	const growth = [
		.02,
		.05,
		.03,
		.06,
		.2,
		.04,
		.07,
		.08,
		.05,
		.17,
		.09,
		.19
	];
	const level = base.slice();
	const out = [];
	for (let year = 2015; year <= 2026; year++) brands.forEach((brand, i) => {
		out.push({
			brand,
			year,
			sales: Math.round(level[i])
		});
		level[i] *= 1 + growth[i] + (rnd() - .5) * .06;
	});
	return out;
}
